+    public void unattachedToLeader() throws Exception {
+        int currentEpoch = currentEpoch();
+        unattachedToCandidate();
+        expectAndGrantVotes(currentEpoch + 1);
+        expectBeginEpoch(currentEpoch + 1);
+    }
